}

function EvaluateLaguerrePolynomialHelper(c: seq<real>, x: real, index: nat): real
  requires |c| > 0
  requires index <= |c|
  decreases |c| - index
{
  if index == |c| then 0.0
  else c[index] * LaguerrePolynomial(index, x) + EvaluateLaguerrePolynomialHelper(c, x, index + 1)
}

