// Represents the Laguerre polynomial L_i(x) evaluated at x
function LaguerrePolynomial(i: nat, x: real): real
  decreases i
{
  if i == 0 then 1.0
  else if i == 1 then 1.0 - x
  else
    // Recurrence relation: (n+1)L_{n+1}(x) = (2n+1-x)L_n(x) - nL_{n-1}(x)
